import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  shadcnSelectContentClasses,
  shadcnSelectGroupClasses,
  shadcnSelectIconClasses,
  shadcnSelectItemClasses,
  shadcnSelectLabelClasses,
  shadcnSelectRootClasses,
  shadcnSelectScrollButtonClasses,
  shadcnSelectSeparatorClasses,
  shadcnSelectTriggerClasses,
  shadcnSelectValueClasses,
  shadcnSelectViewportClasses,
} from "./view";

export { descriptionId, view } from "../../../foldkit/ui/select";
export type { SelectAttributes, ViewConfig } from "../../../foldkit/ui/select";

export {
  shadcnSelectContentClasses,
  shadcnSelectGroupClasses,
  shadcnSelectIconClasses,
  shadcnSelectItemClasses,
  shadcnSelectLabelClasses,
  shadcnSelectRootClasses,
  shadcnSelectScrollButtonClasses,
  shadcnSelectSeparatorClasses,
  shadcnSelectTriggerClasses,
  shadcnSelectValueClasses,
  shadcnSelectViewportClasses,
} from "./view";

export type ShadcnSelectStyle = Readonly<Record<string, string>>;
export type ShadcnSelectChild = Html | string;

export type PartViewConfig = Readonly<{
  children: readonly ShadcnSelectChild[];
  className?: string | undefined;
  style?: ShadcnSelectStyle | undefined;
  testId?: string | undefined;
}>;

export type RootViewConfig = PartViewConfig;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  open: boolean;
  onToggle: ParentMessage;
  children: readonly ShadcnSelectChild[];
  ariaLabel?: string | undefined;
  disabled?: boolean | undefined;
  invalid?: boolean | undefined;
  className?: string | undefined;
  style?: ShadcnSelectStyle | undefined;
}>;

export type ValueViewConfig = Readonly<{
  children: readonly ShadcnSelectChild[];
  placeholder?: boolean | undefined;
  className?: string | undefined;
  style?: ShadcnSelectStyle | undefined;
}>;

export type ContentViewConfig = Readonly<{
  open: boolean;
  children: readonly ShadcnSelectChild[];
  className?: string | undefined;
  style?: ShadcnSelectStyle | undefined;
  testId?: string | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  selected: boolean;
  onSelect: ParentMessage;
  children: readonly ShadcnSelectChild[];
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: ShadcnSelectStyle | undefined;
}>;

export type ScrollButtonViewConfig = Readonly<{
  direction: "up" | "down";
  className?: string | undefined;
  style?: ShadcnSelectStyle | undefined;
}>;

const cn = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const partAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  baseClasses: string,
  className: string | undefined,
  style: ShadcnSelectStyle | undefined,
  testId: string | undefined
) => [
  ...(testId === undefined ? [] : [h.DataAttribute("testid", testId)]),
  ...(style === undefined ? [] : [h.Style(style)]),
  h.Class(cn(baseClasses, className)),
];

export const rootView = <ParentMessage>({
  children,
  className,
  style,
  testId,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    partAttributes(
      h,
      shadcnSelectRootClasses,
      className,
      style,
      testId
    ),
    children
  );
};

export const triggerView = <ParentMessage>({
  open,
  onToggle,
  children,
  ariaLabel,
  disabled = false,
  invalid = false,
  className,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "combobox"),
      h.Attribute("aria-haspopup", "listbox"),
      h.Attribute("aria-expanded", open ? "true" : "false"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      h.Disabled(disabled),
      ...(invalid ? [h.Attribute("aria-invalid", "true")] : []),
      ...(invalid ? [h.Attribute("data-invalid", "")] : []),
      h.OnClick(onToggle),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnSelectTriggerClasses, className)),
    ],
    children
  );
};

export const valueView = <ParentMessage>({
  children,
  placeholder = false,
  className,
  style,
}: ValueViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      ...(placeholder ? [h.Attribute("data-placeholder", "")] : []),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnSelectValueClasses, className)),
    ],
    children
  );
};

export const iconView = <ParentMessage>({
  open,
}: Readonly<{ open: boolean }>): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Attribute("aria-hidden", "true"),
      h.Attribute("data-state", open ? "open" : "closed"),
      h.Class(shadcnSelectIconClasses),
    ],
    ["v"]
  );
};

export const contentView = <ParentMessage>({
  open,
  children,
  className,
  style,
  testId,
}: ContentViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.div([h.Hidden(true)], []);
  }

  return h.div(
    [
      h.Attribute("role", "listbox"),
      h.Attribute("data-state", "open"),
      ...partAttributes(
        h,
        shadcnSelectContentClasses,
        className,
        style,
        testId
      ),
    ],
    children
  );
};

export const viewportView = <ParentMessage>({
  children,
  className,
  style,
  testId,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    partAttributes(
      h,
      shadcnSelectViewportClasses,
      className,
      style,
      testId
    ),
    children
  );
};

export const groupView = <ParentMessage>({
  children,
  className,
  style,
  testId,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      ...partAttributes(
        h,
        shadcnSelectGroupClasses,
        className,
        style,
        testId
      ),
    ],
    children
  );
};

export const labelView = <ParentMessage>({
  children,
  className,
  style,
  testId,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    partAttributes(
      h,
      shadcnSelectLabelClasses,
      className,
      style,
      testId
    ),
    children
  );
};

export const itemView = <ParentMessage>({
  selected,
  onSelect,
  children,
  disabled = false,
  className,
  style,
}: ItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "option"),
      h.Attribute("aria-selected", selected ? "true" : "false"),
      h.Attribute("data-state", selected ? "checked" : "unchecked"),
      h.Disabled(disabled),
      ...(disabled ? [h.Attribute("data-disabled", "")] : []),
      h.OnClick(onSelect),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnSelectItemClasses, className)),
    ],
    children
  );
};

export const separatorView = <ParentMessage>({
  className,
  style,
}: Omit<PartViewConfig, "children">): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "separator"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnSelectSeparatorClasses, className)),
    ],
    []
  );
};

export const scrollButtonView = <ParentMessage>({
  direction,
  className,
  style,
}: ScrollButtonViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("aria-hidden", "true"),
      h.Attribute("data-direction", direction),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(shadcnSelectScrollButtonClasses, className)),
    ],
    [direction === "up" ? "^" : "v"]
  );
};

export const shadcnSelectRootClasses = "relative w-full";

export const shadcnSelectTriggerClasses =
  "inline-flex h-10 w-full items-center justify-between gap-2 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900 shadow-sm transition hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-accent-500 disabled:cursor-not-allowed disabled:opacity-50 data-[invalid]:border-red-500 data-[invalid]:text-red-900";

export const shadcnSelectValueClasses =
  "truncate text-left data-[placeholder]:text-gray-500";

export const shadcnSelectIconClasses =
  "text-gray-500 transition data-[state=open]:rotate-180";

export const shadcnSelectContentClasses =
  "absolute left-0 top-12 z-50 max-h-72 min-w-full overflow-hidden rounded-md border border-gray-200 bg-white p-1 text-gray-950 shadow-lg";

export const shadcnSelectViewportClasses = "max-h-64 overflow-y-auto p-1";

export const shadcnSelectGroupClasses = "p-1";

export const shadcnSelectLabelClasses =
  "px-2 py-1.5 text-xs font-semibold text-gray-500";

export const shadcnSelectItemClasses =
  "relative flex w-full cursor-default select-none items-center rounded-sm px-2 py-1.5 text-left text-sm outline-none transition hover:bg-gray-100 focus:bg-gray-100 disabled:pointer-events-none disabled:opacity-50 data-[state=checked]:bg-gray-100 data-[state=checked]:font-medium";

export const shadcnSelectSeparatorClasses = "-mx-1 my-1 h-px bg-gray-200";

export const shadcnSelectScrollButtonClasses =
  "flex cursor-default items-center justify-center py-1 text-gray-500";

import { Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { describe, expect, test } from "vitest";

import * as Select from "./index";

const ToggledSelect = m("ToggledSelect");
const SelectedPlan = m("SelectedPlan", { value: S.String });

type Message = typeof ToggledSelect.Type | typeof SelectedPlan.Type;

interface Model {
  readonly open: boolean;
  readonly value: string;
}

const update = (model: Model, message: Message): readonly [Model, []] => {
  if (message._tag === "ToggledSelect") {
    return [{ open: !model.open, value: model.value }, []];
  }

  return [{ open: false, value: message.value }, []];
};

const view = (model: Model): Html => {
  const h = html<Message>();

  return Select.rootView<Message>({
    children: [
      Select.triggerView<Message>({
        open: model.open,
        onToggle: ToggledSelect(),
        ariaLabel: "Plan",
        invalid: model.value === "",
        children: [
          Select.valueView<Message>({
            placeholder: model.value === "",
            children: [model.value === "" ? "Select a plan" : model.value],
          }),
          Select.iconView<Message>({ open: model.open }),
        ],
      }),
      Select.contentView<Message>({
        open: model.open,
        children: [
          Select.scrollButtonView<Message>({ direction: "up" }),
          Select.viewportView<Message>({
            children: [
              Select.groupView<Message>({
                children: [
                  Select.labelView<Message>({ children: ["Plans"] }),
                  Select.itemView<Message>({
                    selected: model.value === "Team",
                    onSelect: SelectedPlan({ value: "Team" }),
                    children: ["Team"],
                  }),
                  Select.itemView<Message>({
                    selected: model.value === "Enterprise",
                    onSelect: SelectedPlan({ value: "Enterprise" }),
                    children: ["Enterprise"],
                  }),
                ],
              }),
              Select.separatorView<Message>({}),
            ],
          }),
          Select.scrollButtonView<Message>({ direction: "down" }),
        ],
      }),
    ],
  });
};

describe("shadcn Select registry view", () => {
  test("keeps the native bridge exports available", () => {
    expect(Select.view).toBeTypeOf("function");
    expect(Select.descriptionId).toBeTypeOf("function");
  });

  test("renders composed shadcn select anatomy", () => {
    Scene.scene(
      { update, view },
      Scene.with({ open: false, value: "" }),
      Scene.expect(Scene.role("combobox", { name: "Plan" })).toHaveAttr(
        "aria-expanded",
        "false"
      ),
      Scene.expect(Scene.role("combobox", { name: "Plan" })).toHaveAttr(
        "aria-invalid",
        "true"
      ),
      Scene.expect(Scene.text("Select a plan")).toExist(),
      Scene.click(Scene.role("combobox", { name: "Plan" })),
      Scene.expect(Scene.role("listbox")).toExist(),
      Scene.expect(Scene.text("Plans")).toExist(),
      Scene.expect(Scene.role("option", { name: "Team" })).toHaveAttr(
        "aria-selected",
        "false"
      ),
      Scene.click(Scene.role("option", { name: "Team" })),
      Scene.expect(Scene.text("Team")).toExist(),
      Scene.expect(Scene.role("combobox", { name: "Plan" })).toHaveAttr(
        "aria-expanded",
        "false"
      )
    );
  });
});
